import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

// Shared field styles keep standalone inputs and segmented date/time controls in sync.
export const fieldLabelStyles = "text-sm font-medium text-foreground";
export const fieldDescriptionStyles = "text-xs leading-5 text-muted-foreground";
export const fieldErrorStyles = "text-xs leading-5 text-destructive";

export const fieldInputStyles =
  "min-h-12 w-full cursor-text rounded-lg border border-input bg-card text-base text-foreground shadow-[var(--shadow-card)] outline-none placeholder:text-muted-foreground/80 hover:border-primary/45 motion-safe:transition-[border-color,box-shadow] motion-safe:duration-150 data-[focus-visible]:border-ring data-[focus-visible]:ring-3 data-[focus-visible]:ring-ring/50 data-[invalid]:border-destructive data-[invalid]:ring-3 data-[invalid]:ring-destructive/20 data-[invalid]:hover:border-destructive data-[invalid]:data-[focus-visible]:border-destructive data-[invalid]:data-[focus-visible]:ring-destructive/30 data-[disabled]:cursor-not-allowed data-[disabled]:bg-muted data-[disabled]:opacity-60 data-[disabled]:hover:border-input sm:text-sm";

export const segmentedFieldStyles =
  "flex min-h-12 min-w-0 items-center rounded-lg border border-input bg-card shadow-[var(--shadow-card)] hover:border-primary/45 has-[[data-focus-visible]]:border-ring has-[[data-focus-visible]]:ring-3 has-[[data-focus-visible]]:ring-ring/50 group-data-[invalid]:border-destructive group-data-[invalid]:hover:border-destructive group-data-[invalid]:has-[[data-focus-visible]]:border-destructive group-data-[invalid]:has-[[data-focus-visible]]:ring-destructive/30 group-data-[disabled]:bg-muted group-data-[disabled]:opacity-60 group-data-[disabled]:hover:border-input motion-safe:transition-[border-color,box-shadow] motion-safe:duration-150";

"use client";

import { type HTMLMotionProps, motion, useReducedMotion } from "motion/react";
import {
  Popover as AriaPopover,
  composeRenderProps,
  type PopoverProps,
} from "react-aria-components";
import { cn } from "./utils";

function edgeOffset(placement: string | null) {
  switch (placement) {
    case "top":
      return { x: 0, y: 5 };
    case "left":
      return { x: 5, y: 0 };
    case "right":
      return { x: -5, y: 0 };
    default:
      return { x: 0, y: -5 };
  }
}

type StyledPopoverProps = PopoverProps & { "data-slot"?: string };

export function Popover({
  className,
  "data-slot": dataSlot = "popover",
  ...props
}: StyledPopoverProps) {
  const reduceMotion = useReducedMotion();
  return (
    <AriaPopover
      {...props}
      data-slot={dataSlot}
      render={
        props.render ??
        ((domProps, { placement, isExiting }) => (
          <motion.div
            {...(domProps as HTMLMotionProps<"div">)}
            initial={
              reduceMotion || props.shouldSkipAnimation
                ? false
                : { ...edgeOffset(placement), scale: 0.98 }
            }
            animate={
              isExiting && !reduceMotion
                ? { ...edgeOffset(placement), scale: 0.99 }
                : { x: 0, y: 0, scale: 1 }
            }
            transition={{
              duration: isExiting ? 0.14 : 0.2,
              ease: [0.23, 1, 0.32, 1],
            }}
          />
        ))
      }
      className={composeRenderProps(className, (className) =>
        cn(
          "max-w-[calc(100vw-2rem)] rounded-xl border border-border bg-popover p-5 text-popover-foreground shadow-[var(--shadow-float)] outline-none transition-opacity duration-100 data-[entering]:opacity-0 data-[exiting]:opacity-0 motion-safe:duration-200 motion-safe:data-[exiting]:duration-150 data-[placement=top]:origin-bottom data-[placement=bottom]:origin-top data-[placement=left]:origin-right data-[placement=right]:origin-left",
          className,
        ),
      )}
    />
  );
}

"use client";

import { type HTMLMotionProps, motion, useReducedMotion } from "motion/react";
import { Button, type ButtonProps } from "react-aria-components";

/** React Aria handles presses; Motion supplies the visual feedback. */
export function PressButton({ isDisabled, ...props }: ButtonProps) {
  const reduceMotion = useReducedMotion();

  return (
    <Button
      data-slot="press-button"
      {...props}
      isDisabled={isDisabled}
      render={
        props.render ??
        ((domProps) => (
          <motion.button
            {...(domProps as HTMLMotionProps<"button">)}
            whileTap={reduceMotion || isDisabled ? undefined : { scale: 0.96 }}
            transition={{ duration: 0.14 }}
          />
        ))
      }
    />
  );
}

"use client";

import {
  Tag as AriaTag,
  TagGroup as AriaTagGroup,
  type TagGroupProps as AriaTagGroupProps,
  composeRenderProps,
  Label,
  TagList,
  type TagProps,
} from "react-aria-components";
import { X } from "reicon-react";
import { cn } from "./utils";
import { PressButton } from "./press-button";

export function TagGroup({ className, ...props }: AriaTagGroupProps) {
  return (
    <AriaTagGroup
      {...props}
      data-slot="tag-group"
      className={cn("grid gap-2", className)}
    />
  );
}

export function TagGroupLabel({
  className,
  ...props
}: React.ComponentProps<typeof Label>) {
  return (
    <Label
      {...props}
      data-slot="tag-group-label"
      className={cn("text-sm font-medium", className)}
    />
  );
}

export function TagListView<T extends object>({
  className,
  ...props
}: React.ComponentProps<typeof TagList<T>>) {
  return (
    <TagList
      {...props}
      data-slot="tag-list"
      className={composeRenderProps(className, (className) =>
        cn("flex flex-wrap gap-2.5", className),
      )}
    />
  );
}

export function Tag({ className, children, ...props }: TagProps) {
  return (
    <AriaTag
      {...props}
      data-slot="tag"
      textValue={
        props.textValue ?? (typeof children === "string" ? children : undefined)
      }
      className={composeRenderProps(className, (className) =>
        cn(
          "flex min-h-11 cursor-pointer items-center gap-1 rounded-lg bg-card ps-3 pe-1 text-sm font-medium shadow-[var(--shadow-card)] ring-1 ring-border/80 hover:bg-muted data-[selected]:bg-accent data-[selected]:text-accent-foreground data-[selected]:ring-primary/35 data-[disabled]:cursor-default data-[disabled]:opacity-50 data-[focus-visible]:outline-2 data-[focus-visible]:outline-offset-2 data-[focus-visible]:outline-ring motion-safe:transition-[background-color,box-shadow,scale] motion-safe:duration-150 motion-safe:active:scale-[0.96]",
          className,
        ),
      )}
    >
      {(state) => (
        <>
          <span className={state.allowsRemoving ? "pe-1" : "pe-2"}>
            {typeof children === "function" ? children(state) : children}
          </span>
          {state.allowsRemoving && (
            <PressButton
              slot="remove"
              data-slot="tag-remove"
              aria-label={`Remove ${props.textValue ?? (typeof children === "string" ? children : "tag")}`}
              className="grid size-11 cursor-pointer place-items-center rounded-md text-muted-foreground hover:bg-card hover:text-foreground data-[focus-visible]:outline-2 data-[focus-visible]:outline-ring"
            >
              <X size={14} aria-hidden="true" />
            </PressButton>
          )}
        </>
      )}
    </AriaTag>
  );
}

"use client";

import type { ReactNode } from "react";
import {
  Button as AriaButton,
  ComboBox as AriaComboBox,
  type ComboBoxProps as AriaComboBoxProps,
  ComboBoxValue as AriaComboBoxValue,
  composeRenderProps,
  FieldError,
  Input,
  Label,
  ListBox,
  ListBoxItem,
  Text,
} from "react-aria-components";
import { Check, ChevronDown } from "reicon-react";
import { cn } from "./utils";
import {
  fieldDescriptionStyles,
  fieldErrorStyles,
  fieldInputStyles,
  fieldLabelStyles,
} from "./field-styles";
import { Popover } from "./popover";
import { Tag, TagGroup, TagListView } from "./tag-group";

const comboBoxPopoverStyles =
  "w-[var(--trigger-width)] rounded-lg border-0 p-1.5 ring-1 ring-border/70";
const comboBoxItemStyles =
  "group/item flex min-h-11 cursor-pointer items-center justify-between gap-3 rounded-md px-2.5 py-2 text-sm outline-none hover:bg-muted data-[focused]:bg-muted data-[focus-visible]:-outline-offset-2 data-[focus-visible]:outline-2 data-[focus-visible]:outline-ring data-[selected]:bg-accent data-[selected]:text-accent-foreground data-[disabled]:cursor-default data-[disabled]:opacity-50";

export interface ComboBoxOption {
  id: string;
  name: string;
  description?: string;
}

type ComboBoxBaseProps<M extends "single" | "multiple"> = Omit<
  AriaComboBoxProps<ComboBoxOption, M>,
  "children" | "className"
> & {
  label?: string;
  description?: string;
  options?: ComboBoxOption[];
  placeholder?: string;
  className?: AriaComboBoxProps<ComboBoxOption, M>["className"];
  children?: AriaComboBoxProps<ComboBoxOption, M>["children"];
};

export interface ComboBoxProps extends ComboBoxBaseProps<"single"> {
  selectionMode?: "single";
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
}

export interface MultiSelectComboBoxProps
  extends ComboBoxBaseProps<"multiple"> {
  selectionMode: "multiple";
}

export function ComboBox(props: ComboBoxProps): React.ReactElement;
export function ComboBox(props: MultiSelectComboBoxProps): React.ReactElement;
export function ComboBox(props: ComboBoxProps | MultiSelectComboBoxProps) {
  if (props.selectionMode === "multiple") {
    return <MultipleComboBox {...props} />;
  }
  return <SingleComboBox {...props} />;
}

function SingleComboBox({
  label,
  description,
  options,
  placeholder = "Search options",
  className,
  children,
  value,
  defaultValue,
  onValueChange,
  ...props
}: ComboBoxProps) {
  return (
    <AriaComboBox
      {...props}
      data-slot="combo-box"
      selectedKey={value ?? props.selectedKey}
      defaultSelectedKey={defaultValue ?? props.defaultSelectedKey}
      onSelectionChange={(key) => {
        props.onSelectionChange?.(key);
        onValueChange?.(key === null ? "" : String(key));
      }}
      className={composeRenderProps(className, (className) =>
        cn("flex w-full flex-col gap-2", className),
      )}
    >
      {children ?? (
        <ComboBoxDefaults
          label={label}
          description={description}
          options={options}
          placeholder={placeholder}
        />
      )}
    </AriaComboBox>
  );
}

function MultipleComboBox({
  label,
  description,
  options,
  placeholder = "Search options",
  className,
  children,
  ...props
}: MultiSelectComboBoxProps) {
  return (
    <AriaComboBox
      {...props}
      data-slot="combo-box"
      className={composeRenderProps(className, (className) =>
        cn("flex w-full flex-col gap-2", className),
      )}
    >
      {children ?? (
        <ComboBoxDefaults
          label={label}
          description={description}
          options={options}
          placeholder={placeholder}
          multiple
        />
      )}
    </AriaComboBox>
  );
}

function ComboBoxDefaults({
  label,
  description,
  options,
  placeholder,
  multiple = false,
}: {
  label?: string;
  description?: string;
  options?: ComboBoxOption[];
  placeholder: string;
  multiple?: boolean;
}) {
  return (
    <>
      {label && <ComboBoxLabel>{label}</ComboBoxLabel>}
      <div className="relative flex items-center">
        <ComboBoxInput placeholder={placeholder} />
        <ComboBoxTrigger />
      </div>
      {multiple && <ComboBoxTags />}
      {description && <ComboBoxDescription>{description}</ComboBoxDescription>}
      <ComboBoxError />
      <Popover
        data-slot="combo-box-content"
        placement="bottom start"
        offset={7}
        className={comboBoxPopoverStyles}
      >
        <ListBox
          data-slot="combo-box-list-box"
          items={options ?? []}
          renderEmptyState={() => (
            <div className="px-3 py-3 text-sm text-muted-foreground">
              No matching options.
            </div>
          )}
          className="grid max-h-64 gap-1 overflow-y-auto outline-none"
        >
          {(option) => (
            <ListBoxItem
              data-slot="combo-box-item"
              id={option.id}
              textValue={option.name}
              className={comboBoxItemStyles}
            >
              <span className="min-w-0">
                <span className="block font-medium">{option.name}</span>
                {option.description && (
                  <span className="mt-0.5 block text-xs text-muted-foreground group-data-[selected]/item:text-accent-foreground">
                    {option.description}
                  </span>
                )}
              </span>
              <Check
                size={15}
                aria-hidden="true"
                className="shrink-0 opacity-0 group-data-[selected]/item:opacity-100"
              />
            </ListBoxItem>
          )}
        </ListBox>
      </Popover>
    </>
  );
}

export function ComboBoxTags({
  className,
  label = "Selected options",
  emptyText = "No options selected.",
}: {
  className?: string;
  label?: string;
  emptyText?: string;
}) {
  return (
    <AriaComboBoxValue<ComboBoxOption>
      data-slot="combo-box-tags"
      className={cn("min-w-0", className)}
    >
      {({ state }) => (
        <TagGroup
          aria-label={label}
          onRemove={(keys) => {
            if (Array.isArray(state.value)) {
              state.setValue(state.value.filter((key) => !keys.has(key)));
            }
          }}
        >
          <TagListView
            items={state.selectedItems.map((item) => ({
              id: item.key,
              name: item.textValue,
            }))}
            renderEmptyState={() => (
              <span className="text-sm text-muted-foreground">{emptyText}</span>
            )}
          >
            {(item) => (
              <Tag id={item.id} textValue={item.name}>
                {item.name}
              </Tag>
            )}
          </TagListView>
        </TagGroup>
      )}
    </AriaComboBoxValue>
  );
}

export function ComboBoxLabel({
  className,
  ...props
}: React.ComponentProps<typeof Label>) {
  return (
    <Label
      {...props}
      data-slot="combo-box-label"
      className={cn(fieldLabelStyles, className)}
    />
  );
}

export function ComboBoxInput({
  className,
  ...props
}: React.ComponentProps<typeof Input>) {
  return (
    <Input
      {...props}
      data-slot="combo-box-input"
      className={composeRenderProps(className, (className) =>
        cn(fieldInputStyles, "ps-3.5 pe-12", className),
      )}
    />
  );
}

export function ComboBoxTrigger({
  className,
  children,
  ...props
}: React.ComponentProps<typeof AriaButton>) {
  return (
    <AriaButton
      {...props}
      data-slot="combo-box-trigger"
      aria-label={props["aria-label"] ?? "Show options"}
      className={composeRenderProps(className, (className) =>
        cn(
          "absolute inset-y-0 end-1 my-auto grid size-11 cursor-pointer place-items-center rounded-md text-muted-foreground outline-none data-[disabled]:cursor-default data-[disabled]:opacity-50 hover:bg-muted hover:text-foreground data-[focus-visible]:outline-2 data-[focus-visible]:outline-ring",
          className,
        ),
      )}
    >
      {children ?? <ChevronDown size={16} aria-hidden="true" />}
    </AriaButton>
  );
}

export function ComboBoxContent({
  className,
  children,
  ...props
}: React.ComponentProps<typeof Popover>) {
  return (
    <Popover
      {...props}
      data-slot="combo-box-content"
      placement={props.placement ?? "bottom start"}
      offset={props.offset ?? 7}
      className={composeRenderProps(className, (className) =>
        cn(comboBoxPopoverStyles, className),
      )}
    >
      <ListBox
        data-slot="combo-box-list-box"
        className="grid max-h-64 gap-1 overflow-y-auto outline-none"
        renderEmptyState={() => (
          <div className="px-3 py-3 text-sm text-muted-foreground">
            No matching options.
          </div>
        )}
      >
        {children}
      </ListBox>
    </Popover>
  );
}

export function ComboBoxItem({
  className,
  children,
  ...props
}: Omit<React.ComponentProps<typeof ListBoxItem>, "children"> & {
  children: ReactNode;
}) {
  return (
    <ListBoxItem
      {...props}
      data-slot="combo-box-item"
      className={composeRenderProps(className, (className) =>
        cn(comboBoxItemStyles, className),
      )}
    >
      {children}
      <Check
        size={15}
        aria-hidden="true"
        className="ms-auto shrink-0 opacity-0 group-data-[selected]/item:opacity-100"
      />
    </ListBoxItem>
  );
}

export function ComboBoxDescription({
  className,
  ...props
}: React.ComponentProps<typeof Text>) {
  return (
    <Text
      {...props}
      slot="description"
      data-slot="combo-box-description"
      className={cn(fieldDescriptionStyles, className)}
    />
  );
}

export function ComboBoxError({
  className,
  ...props
}: React.ComponentProps<typeof FieldError>) {
  return (
    <FieldError
      {...props}
      data-slot="combo-box-error"
      className={cn(fieldErrorStyles, className)}
    />
  );
}
